<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>İptal talepleri ve politikası</title><style>
*{box-sizing:border-box}body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:28px auto;padding:0 16px}.panel,.item{background:#fff;border:1px solid #e4ebe5;border-radius:14px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}label{font-size:13px;font-weight:700}input,textarea,select{display:block;width:100%;padding:10px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;font:inherit}button{padding:10px 14px;border:0;border-radius:8px;background:#176b50;color:#fff;font-weight:700}.muted{font-size:13px;color:#718077;line-height:1.5}.row{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.actions{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.actions form{display:flex;gap:8px;align-items:end}.actions textarea{min-width:180px;min-height:40px}.danger{background:#a43b32}.status{font-weight:700}@media(max-width:650px){.grid{grid-template-columns:1fr}.actions form{display:grid;width:100%}}
</style></head><body><main class="wrap"><h1>İptal talepleri ve politikası</h1><p class="muted">İptal politikası yeni taleplerde anlık olarak hesaplanır ve talep oluşturulduğunda kayıt altına alınır. İade ödemesi otomatik gönderilmez; onaylanan talebin iadesi Finans ve Ödemeler ekranından ayrıca gerçekleştirilir.</p>
<section class="panel"><h2>Genel iptal politikası</h2><form method="post" action="<?= e(app_url('/admin/cancellations/policy')) ?>"><?= csrf_field() ?><div class="grid"><label>Ücretsiz iptal için gereken gün<input type="number" name="free_days" min="0" max="365" value="<?= (int)$policy['free_days'] ?>"></label><label>Bu sürede iade oranı (%)<input type="number" name="early_percent" min="0" max="100" value="<?= (int)$policy['early_percent'] ?>"></label><label>Süre dolduktan sonra iade oranı (%)<input type="number" name="late_percent" min="0" max="100" value="<?= (int)$policy['late_percent'] ?>"></label></div><p class="muted">Örnek: 7 gün / %100 / %0 ayarı, giriş tarihine en az 7 gün varsa tam; daha az varsa iadesiz iptal hakkı hesaplar.</p><button type="submit">Politikayı kaydet</button></form></section>
<h2>İptal talepleri</h2><?php foreach($requests as $request): ?><article class="item"><div class="row"><div><strong><?= e($request['property_title']) ?></strong><div class="muted"><?= e($request['booking_code']) ?> · <?= e($request['guest_name']) ?> · <?= e($request['guest_email']) ?></div><div class="muted"><?= e(date('d.m.Y',strtotime($request['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($request['check_out']))) ?></div><p><?= e($request['reason']?:'İptal nedeni belirtilmedi.') ?></p></div><div><div class="status"><?= e(['pending'=>'Bekliyor','approved'=>'Onaylandı','rejected'=>'Reddedildi'][$request['status']]??$request['status']) ?></div><strong><?= e(number_format((float)$request['refund_amount'],2,',','.')) ?> <?= e($request['currency']) ?> iade hesabı</strong><div class="muted"><?= (int)$request['refund_percent_snapshot'] ?>% · girişe <?= (int)$request['days_before_checkin'] ?> gün kala</div></div></div><?php if($request['status']==='pending'): ?><div class="actions"><form method="post" action="<?= e(app_url('/admin/cancellations/review')) ?>"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><input type="hidden" name="decision" value="approved"><textarea name="decision_note" maxlength="1000" placeholder="Karar notu (isteğe bağlı)"></textarea><button type="submit">İptali onayla</button></form><form method="post" action="<?= e(app_url('/admin/cancellations/review')) ?>"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><input type="hidden" name="decision" value="rejected"><textarea name="decision_note" maxlength="1000" placeholder="Ret nedeni"></textarea><button class="danger" type="submit">Reddet</button></form></div><?php elseif(!empty($request['decision_note'])): ?><p class="muted">Karar notu: <?= e($request['decision_note']) ?></p><?php endif; ?></article><?php endforeach; ?><?php if(!$requests): ?><p class="panel">Henüz iptal talebi bulunmuyor.</p><?php endif; ?></main></body></html>